import unitData from "../../../../data/autobattler/units.json";

// =========================================================
// SHADOW ARENA - static game data (units, Boss routes,
// synergies, keyword texts). Pure data: imported by the engine
// (browser + server replay) and by the UI.
//
// data/autobattler/units.json is generated by
// data/autobattler/build-units.mjs from the local card catalog.
// =========================================================

export type Attribute =
  | "DARK"
  | "LIGHT"
  | "EARTH"
  | "WATER"
  | "FIRE"
  | "WIND";

export type Tribe =
  | "Dragon"
  | "Spellcaster"
  | "Warrior"
  | "Fiend"
  | "Zombie"
  | "Machine"
  | "Beast"
  | "Aqua";

export type Ability =
  | "taunt"
  | "shield"
  | "revive"
  | "pierce"
  | "rally"
  | "lastwill"
  | "spawn"
  | "double"
  | "venom"
  | "ascend"
  | "ambush";

export type CombatKeyword =
  Exclude<
    Ability,
    "rally" | "ascend"
  >;

export type UnitDef = {
  id: string;
  name: string;
  tier: number;
  attribute: Attribute;
  race: string;
  tribe: Tribe | null;
  level: number;
  cardAtk: number;
  cardDef: number;
  atk: number;
  hp: number;
  ability: Ability;
  power: number;
  rallyBy?: "tribe" | "attribute";
  img: string;
  art: string | null;
  /** Fusion / Xyz "specials": made in a run, never in the shop. */
  kind?: "fusion" | "xyz";
  /** Xyz only: made from two units of this Level. */
  rank?: number;
};

export type FusionMaterial =
  | {
      unit: string;
      golden?: boolean;
    }
  | {
      tribe: Tribe;
    };

export type FusionRecipe = {
  result: string;
  materials: FusionMaterial[];
};

export type TrapEffect =
  | "destroy_min_atk"
  | "bounce"
  | "no_castle_damage"
  | "destroy"
  | "reflect"
  | "revive"
  | "destroy_two"
  | "banish"
  | "wipe_lane";

/** A Trap Card: set face-down on one lane, triggers once per combat. */
export type TrapDef = {
  id: string;
  name: string;
  tier: number;
  effect: TrapEffect;
  trigger: "enter" | "death" | "castle";
  value: number;
  img: string;
  art: string | null;
};

export type BossRouteUnit = {
  name: string;
  attribute: string | null;
  race: string | null;
  level: number;
  cardAtk: number;
  cardDef: number;
  boss: boolean;
  img: string;
  art: string | null;
};

export type BossRoute = {
  code: string;
  name: string;
  order: number;
  keywords: CombatKeyword[];
  units: BossRouteUnit[];
};

const data =
  unitData as unknown as {
    units: UnitDef[];
    specials: UnitDef[];
    fusions: FusionRecipe[];
    traps: TrapDef[];
    routes: BossRoute[];
  };

/** Shop units (the run's shared pool). */
export const UNITS: readonly UnitDef[] =
  data.units;

/** Fusion + Xyz monsters: only made in a run, never in the pool. */
export const SPECIALS: readonly UnitDef[] =
  data.specials;

export const FUSIONS: readonly FusionRecipe[] =
  data.fusions;

/** Trap Cards (in the shop pool next to the units). */
export const TRAPS: readonly TrapDef[] =
  data.traps;

export const TRAP_BY_ID: ReadonlyMap<string, TrapDef> =
  new Map(
    TRAPS.map(
      (trap) => [trap.id, trap]
    )
  );

/** One-line rules text for a trap in the lane game. */
export function trapText(
  trap: Pick<TrapDef, "effect" | "value">
) {
  switch (trap.effect) {
    case "destroy_min_atk":
      return `The first enemy attacker with ${trap.value}+ ATK that enters your half of this lane is destroyed.`;
    case "bounce":
      return "The first enemy attacker that enters your half of this lane is sent back to its start.";
    case "no_castle_damage":
      return "Your castle takes no damage from this lane this combat.";
    case "destroy":
      return "The first enemy attacker that enters your half of this lane is destroyed.";
    case "reflect":
      return "The first enemy attacker that enters your half of this lane is sent back, and its castle damage hits the enemy castle.";
    case "revive":
      return "The first of your monsters destroyed in this lane comes back with full DEF.";
    case "destroy_two":
      return "When an enemy attacker enters your half of this lane, destroy it and the next enemy attacker in this lane.";
    case "banish":
      return "The first enemy attacker that enters your half of this lane is banished (no Reborn, no Last Will).";
    case "wipe_lane":
      return "When an enemy attacker enters your half of this lane, destroy EVERY monster in this lane (yours too).";
  }
}

export const XYZ_BY_RANK: ReadonlyMap<number, UnitDef> =
  new Map(
    SPECIALS.filter(
      (unit) => unit.kind === "xyz" && unit.rank !== undefined
    ).map(
      (unit) => [unit.rank as number, unit]
    )
  );

export const ROUTES: readonly BossRoute[] =
  [...data.routes].sort(
    (a, b) => a.order - b.order
  );

export const UNIT_BY_ID: ReadonlyMap<string, UnitDef> =
  new Map(
    [...UNITS, ...SPECIALS].map(
      (unit) => [unit.id, unit]
    )
  );

export const ROUTE_BY_CODE: ReadonlyMap<string, BossRoute> =
  new Map(
    ROUTES.map(
      (route) => [route.code, route]
    )
  );

export const ATTRIBUTES: readonly Attribute[] = [
  "DARK",
  "LIGHT",
  "EARTH",
  "WATER",
  "FIRE",
  "WIND",
];

export const TRIBES: readonly Tribe[] = [
  "Dragon",
  "Spellcaster",
  "Warrior",
  "Fiend",
  "Zombie",
  "Machine",
  "Beast",
  "Aqua",
];

export const ABILITY_LABEL: Record<Ability, string> = {
  taunt: "Guardian",
  shield: "Spellbound",
  revive: "Reborn",
  pierce: "Pierce",
  rally: "Rally",
  lastwill: "Last Will",
  spawn: "Summon",
  double: "Double Attack",
  venom: "Venom",
  ascend: "Ascend",
  ambush: "Ambush",
};

/** One-line rules text for a unit's ability (golden = doubled power). */
export function abilityText(
  ability: Ability,
  power: number,
  extra?: {
    rallyBy?: "tribe" | "attribute";
    tribe?: Tribe | null;
    attribute?: string | null;
  }
) {
  switch (ability) {
    case "taunt":
      return "Guardian: in DEF position it is a wall with triple DEF.";
    case "shield":
      return "Spellbound: the first hit it takes deals no damage.";
    case "revive":
      return "Reborn: the first time it dies, it returns with 1 health.";
    case "pierce":
      return "Pierce: excess damage hits the enemy behind its target, or the castle.";
    case "rally": {
      const group =
        extra?.rallyBy === "tribe"
          ? extra.tribe ?? "same-type"
          : extra?.attribute ?? "same-attribute";

      return `Rally: when played, give your other ${group} units +${power}/+${power}.`;
    }
    case "lastwill":
      return `Last Will: when it dies, give a random ally +${power}/+${power}.`;
    case "spawn":
      return `Summon: when it dies, summon a ${power}/${power} Token.`;
    case "double":
      return "Double Attack: attacks twice each time.";
    case "venom":
      return "Venom: destroys any unit it damages.";
    case "ascend":
      return `Ascend: at the end of your turn, gain +${power}/+${power}.`;
    case "ambush":
      return `Ambush: at the start of combat, deal ${power} damage to the front enemy in its lane (or a random enemy).`;
  }
}

